INSERT INTO `db2_garr_building` (`id`,`horde_name`,`alliance_name`,`description`,`tooltip`,`garr_type_id`,`building_type`,`horde_game_object_id`,`alliance_game_object_id`,`garr_site_id`,`upgrade_level`,`build_seconds`,`currency_type_id`,`currency_qty`,`horde_ui_texture_kit_id`,`alliance_ui_texture_kit_id`,`icon_file_data_id`,`alliance_scene_script_package_id`,`horde_scene_script_package_id`,`max_assignments`,`shipment_capacity`,`garr_ability_id`,`bonus_garr_ability_id`,`gold_cost`,`flags`) VALUES
(8,'War Mill','Dwarven Bunker','This structure stores and maintains the garrison\'s armaments.','Doubles the chance for your quest rewards to get a rare or epic Bonus Upgrade, and increases the potency of the upgrade. Allows the collection of armor scraps from the orc clans of Draenor for armor transmogrification use.',2,10,230406,224548,0,1,3600,824,150,15,14,975736,1194,1193,0,0,0,0,150,1),
(9,'War Mill','Dwarven Bunker','This structure stores and maintains the garrison\'s armaments.','Opens up work orders for follower weapons and armor in exchange for garrison resources.  Also, new armor transmogrification items unlock.',2,10,230407,224549,0,2,3600,824,900,18,16,975736,1196,1195,0,14,0,0,300,1),
(10,'War Mill','Dwarven Bunker','This structure stores and maintains the garrison\'s armaments.','Grants 1 of your 3 seals of inevitable fate (raid bonus loot roll) at no cost each week.',2,10,230409,224550,0,3,3600,824,1200,19,17,975736,1198,1197,0,21,0,0,500,1),
(24,'Barn','Barn','The Barn houses captured creatures that provide the garrison with leather, meat, and fur.','Allows you to capture clefthoof, elekk, wolves, and talbuk for leather and fur.  Used for leatherworking and tailoring recipes.',2,3,230410,224795,0,1,3600,824,100,131,3,975737,1220,1219,0,7,0,0,150,1),
(25,'Barn','Barn','The Barn houses captured creatures that provide the garrison with leather, meat, and fur.','Allows you to capture boars and riverbeasts for rare meats used to create the most powerful food.',2,3,230411,224796,0,2,3600,824,300,132,57,975737,1222,1221,0,14,62,0,300,1),
(26,'Barracks','Barracks','The Barracks houses your garrison\'s military forces and followers.','Unlocks patrol missions.  Patrol missions have higher than normal follower experience rewards.',2,8,230412,224797,0,1,3600,824,150,142,36,975738,1224,1223,0,1,0,0,10,1),
